<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio File Manager V12.7 — producer asset controls */
function tuff_beatz_file_manager_categories(){return array('source'=>'Source Files','stems'=>'Stems','mixes'=>'Mix Versions','masters'=>'Masters','final'=>'Final Delivery');}
function tuff_beatz_file_manager_bucket($file){$explicit=sanitize_key($file['studio_category']??'');$cats=tuff_beatz_file_manager_categories();if(isset($cats[$explicit]))return $explicit;$cat=sanitize_key($file['category']??'source');$v=strtolower((string)($file['version']??''));$n=strtolower((string)($file['name']??''));if($cat==='delivery'){if(strpos($v,'final')!==false||strpos($v,'delivery')!==false||strpos($n,'final')!==false)return 'final';if(strpos($v,'master')!==false||strpos($n,'master')!==false)return 'masters';return 'mixes';}if(strpos($v,'stem')!==false||strpos($n,'stem')!==false)return 'stems';return 'source';}
function tuff_beatz_file_manager_label($bucket){$m=tuff_beatz_file_manager_categories();return $m[$bucket]??'Project Files';}
function tuff_beatz_file_manager_icon($name){$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(in_array($ext,array('wav','aiff','aif','mp3','m4a'),true))return '♫';if($ext==='zip')return 'ZIP';if($ext==='pdf')return 'PDF';if(in_array($ext,array('mid','midi'),true))return 'MIDI';return 'FILE';}
function tuff_beatz_file_manager_producer_can_manage($id){return is_user_logged_in()&&current_user_can('edit_post',(int)$id);}
function tuff_beatz_file_manager_upload(){ $id=(int)($_POST['request_id']??0);$r=function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($id).'#files':home_url('/project-dashboard/');if(!$id||!is_user_logged_in()||!function_exists('tuff_beatz_user_project_permission')||!tuff_beatz_user_project_permission($id,'upload')){wp_safe_redirect(home_url('/start-a-project/'));exit;}if(!isset($_POST['tb_fm_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_fm_nonce'])),'tb_fm_upload_'.$id)){wp_safe_redirect($r);exit;}$studio=sanitize_key(wp_unslash($_POST['studio_category']??'source'));$cats=tuff_beatz_file_manager_categories();if(!isset($cats[$studio]))$studio='source';$version=sanitize_text_field(wp_unslash($_POST['upload_version']??''));if(!$version)$version=$cats[$studio];$vault_category=in_array($studio,array('mixes','masters','final'),true)?'delivery':'source';$new=function_exists('tuff_beatz_vault_save_files')?tuff_beatz_vault_save_files($id,'project_files',$vault_category,$version):array();if($new){$ids=array();foreach($new as $f)$ids[]=$f['id']??'';$all=tuff_beatz_vault_files($id);foreach($all as &$f){if(in_array($f['id']??'',$ids,true))$f['studio_category']=$studio;}unset($f);update_post_meta($id,'_tb_vault_files',$all);if($studio==='mixes'&&function_exists('tuff_beatz_workflow_apply_status'))tuff_beatz_workflow_apply_status($id,'revision','Studio File Manager Mix Upload');elseif($studio==='masters'&&function_exists('tuff_beatz_workflow_apply_status'))tuff_beatz_workflow_apply_status($id,'mastering','Studio File Manager Master Upload');elseif($studio==='final'&&function_exists('tuff_beatz_workflow_apply_status'))tuff_beatz_workflow_apply_status($id,'delivery','Studio File Manager Final Delivery');if(function_exists('tuff_beatz_add_activity'))tuff_beatz_add_activity($id,'file',count($new).' file(s) uploaded to '.$cats[$studio]);}wp_safe_redirect(add_query_arg(array('files_added'=>(string)count($new),'file_category'=>$studio),$r));exit;}
add_action('admin_post_tb_file_manager_upload','tuff_beatz_file_manager_upload');
function tuff_beatz_file_manager_update(){ $id=(int)($_POST['request_id']??0);$fid=sanitize_text_field(wp_unslash($_POST['file_id']??''));$r=tuff_beatz_project_dashboard_url($id).'#files';if(!$id||!$fid||!tuff_beatz_file_manager_producer_can_manage($id)){wp_safe_redirect($r);exit;}if(!isset($_POST['tb_fm_manage_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_fm_manage_nonce'])),'tb_fm_manage_'.$id.'_'.$fid)){wp_safe_redirect($r);exit;}$cats=tuff_beatz_file_manager_categories();$studio=sanitize_key(wp_unslash($_POST['studio_category']??'source'));if(!isset($cats[$studio]))$studio='source';$version=sanitize_text_field(wp_unslash($_POST['version']??''));$display=sanitize_file_name(wp_unslash($_POST['display_name']??''));$all=tuff_beatz_vault_files($id);$changed=false;foreach($all as &$f){if(($f['id']??'')!==$fid)continue;$ext=strtolower(pathinfo($f['name']??'',PATHINFO_EXTENSION));if($display){$newext=strtolower(pathinfo($display,PATHINFO_EXTENSION));if(!$newext&&$ext)$display.='.'.$ext;if($ext&&strtolower(pathinfo($display,PATHINFO_EXTENSION))!==$ext)$display=pathinfo($display,PATHINFO_FILENAME).'.'.$ext;$f['name']=$display;}$f['version']=$version?:($f['version']??'Project File');$f['studio_category']=$studio;$f['category']=in_array($studio,array('mixes','masters','final'),true)?'delivery':'source';$f['updated_at']=current_time('mysql');$f['updated_by']=get_current_user_id();$changed=true;break;}unset($f);if($changed){update_post_meta($id,'_tb_vault_files',$all);if(function_exists('tuff_beatz_add_activity'))tuff_beatz_add_activity($id,'file','File metadata updated: '.$fid);}wp_safe_redirect(add_query_arg('file_updated',$changed?'1':'0',$r));exit;}
add_action('admin_post_tb_file_manager_update','tuff_beatz_file_manager_update');
function tuff_beatz_file_manager_archive(){ $id=(int)($_POST['request_id']??0);$fid=sanitize_text_field(wp_unslash($_POST['file_id']??''));$r=tuff_beatz_project_dashboard_url($id).'#files';if(!$id||!$fid||!tuff_beatz_file_manager_producer_can_manage($id)){wp_safe_redirect($r);exit;}if(!isset($_POST['tb_fm_manage_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_fm_manage_nonce'])),'tb_fm_manage_'.$id.'_'.$fid)){wp_safe_redirect($r);exit;}$all=tuff_beatz_vault_files($id);$changed=false;foreach($all as &$f){if(($f['id']??'')===$fid){$f['archived']=empty($f['archived'])?1:0;$f['archived_at']=$f['archived']?current_time('mysql'):'';$f['archived_by']=$f['archived']?get_current_user_id():0;$changed=true;break;}}unset($f);if($changed){update_post_meta($id,'_tb_vault_files',$all);if(function_exists('tuff_beatz_add_activity'))tuff_beatz_add_activity($id,'file','Vault file archive state changed');}wp_safe_redirect(add_query_arg('file_archived',$changed?'1':'0',$r));exit;}
add_action('admin_post_tb_file_manager_archive','tuff_beatz_file_manager_archive');
function tuff_beatz_file_manager_delete(){ $id=(int)($_POST['request_id']??0);$fid=sanitize_text_field(wp_unslash($_POST['file_id']??''));$r=tuff_beatz_project_dashboard_url($id).'#files';if(!$id||!$fid||!tuff_beatz_file_manager_producer_can_manage($id)){wp_safe_redirect($r);exit;}if(!isset($_POST['tb_fm_delete_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_fm_delete_nonce'])),'tb_fm_delete_'.$id.'_'.$fid)){wp_safe_redirect($r);exit;}$all=tuff_beatz_vault_files($id);$keep=array();$deleted=null;foreach($all as $f){if(($f['id']??'')===$fid){$deleted=$f;continue;}$keep[]=$f;}if($deleted){$path=function_exists('tuff_beatz_vault_path')?tuff_beatz_vault_path($id,$deleted):'';if($path&&is_file($path)&&!@unlink($path)){wp_safe_redirect(add_query_arg('file_deleted','0',$r));exit;}update_post_meta($id,'_tb_vault_files',$keep);$review=get_post_meta($id,'_tb_mix_review_status',true);if(is_array($review)&&isset($review[$fid])){unset($review[$fid]);update_post_meta($id,'_tb_mix_review_status',$review);}if(get_post_meta($id,'_tb_approved_mix_file',true)===$fid)delete_post_meta($id,'_tb_approved_mix_file');if(function_exists('tuff_beatz_add_activity'))tuff_beatz_add_activity($id,'file','Vault file permanently deleted: '.($deleted['name']??$fid));}wp_safe_redirect(add_query_arg('file_deleted',$deleted?'1':'0',$r));exit;}
add_action('admin_post_tb_file_manager_delete','tuff_beatz_file_manager_delete');
function tuff_beatz_file_manager_render(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id||!function_exists('tuff_beatz_user_project_permission')||!tuff_beatz_user_project_permission($id,'view'))return;$allfiles=function_exists('tuff_beatz_vault_files')?tuff_beatz_vault_files($id):array();$files=array_values(array_filter($allfiles,function($f){return empty($f['archived']);}));$archived=array_values(array_filter($allfiles,function($f){return !empty($f['archived']);}));$groups=array('source'=>array(),'stems'=>array(),'mixes'=>array(),'masters'=>array(),'final'=>array());foreach($files as $f)$groups[tuff_beatz_file_manager_bucket($f)][]=$f;$can_upload=tuff_beatz_user_project_permission($id,'upload');$can_manage=tuff_beatz_file_manager_producer_can_manage($id);echo '<template id="tb-file-manager-template"><section id="files" class="tb-portal-card tb-workspace-section tb-file-manager"><div class="tb-fm-head"><div><p class="tb-card-kicker">STUDIO FILE MANAGER</p><h2>Files & Versions</h2><p>Private project assets organized by explicit production category.</p></div><div class="tb-fm-total"><strong>'.esc_html(count($files)).'</strong><span>ACTIVE FILES</span></div></div><div class="tb-fm-tabs">';foreach($groups as $key=>$items)echo '<button type="button" data-fm-filter="'.esc_attr($key).'">'.esc_html(tuff_beatz_file_manager_label($key)).'<b>'.esc_html(count($items)).'</b></button>';if($can_manage)echo '<button type="button" data-fm-filter="archive">Archive<b>'.esc_html(count($archived)).'</b></button>';echo '</div><div class="tb-fm-groups">';foreach($groups as $key=>$items){echo '<section class="tb-fm-group" data-fm-group="'.esc_attr($key).'">';tuff_beatz_file_manager_group_content($id,$key,$items,$can_manage);echo '</section>';}if($can_manage){echo '<section class="tb-fm-group" data-fm-group="archive">';tuff_beatz_file_manager_group_content($id,'archive',$archived,true);echo '</section>';}echo '</div>';if($can_upload){echo '<form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'" class="tb-fm-upload"><input type="hidden" name="action" value="tb_file_manager_upload"><input type="hidden" name="request_id" value="'.esc_attr($id).'">';wp_nonce_field('tb_fm_upload_'.$id,'tb_fm_nonce');echo '<div><small>ADD TO PRIVATE VAULT</small><h3>Upload Project Files</h3><p>Choose exactly where these files belong in the production workflow.</p></div><label class="tb-fm-field"><span>Category</span><select name="studio_category">';foreach(tuff_beatz_file_manager_categories() as $key=>$label)echo '<option value="'.esc_attr($key).'">'.esc_html($label).'</option>';echo '</select></label><label class="tb-fm-field"><span>Version</span><input name="upload_version" type="text" placeholder="Example: Vocal Stems V2"></label><label class="tb-fm-field tb-fm-filepick"><span>Files</span><input name="project_files[]" type="file" multiple accept=".wav,.aiff,.aif,.mp3,.m4a,.zip,.pdf,.txt,.mid,.midi"></label><button class="btn btn-gold" type="submit">Upload Securely</button></form>';}echo '</section></template><script>document.addEventListener("DOMContentLoaded",function(){var t=document.getElementById("tb-file-manager-template"),old=document.getElementById("files");if(t&&old){old.replaceWith(t.content.cloneNode(true));var root=document.getElementById("files"),buttons=root?root.querySelectorAll("[data-fm-filter]"):[];function show(key){root.querySelectorAll("[data-fm-group]").forEach(function(g){g.hidden=g.getAttribute("data-fm-group")!==key;});buttons.forEach(function(b){b.classList.toggle("is-active",b.getAttribute("data-fm-filter")===key);});}buttons.forEach(function(b){b.addEventListener("click",function(){show(b.getAttribute("data-fm-filter"));});});root.querySelectorAll("[data-fm-edit]").forEach(function(b){b.addEventListener("click",function(){var p=b.closest(".tb-fm-asset"),e=p&&p.querySelector(".tb-fm-editor");if(e)e.hidden=!e.hidden;});});var first=Array.prototype.find.call(buttons,function(b){return parseInt((b.querySelector("b")||{}).textContent||"0",10)>0;})||buttons[0];if(first)show(first.getAttribute("data-fm-filter"));}});</script>';}
function tuff_beatz_file_manager_group_content($id,$key,$items,$can_manage){$title=$key==='archive'?'Archived Files':tuff_beatz_file_manager_label($key);echo '<div class="tb-fm-group-head"><div><small>'.esc_html(strtoupper($key)).'</small><h3>'.esc_html($title).'</h3></div><span>'.esc_html(count($items)).' item'.(count($items)===1?'':'s').'</span></div>';if(!$items){echo '<div class="tb-fm-empty">No '.esc_html(strtolower($title)).' yet.</div>';return;}foreach(array_reverse($items) as $f){$u=(int)($f['uploaded_by']??0);$user=$u?get_userdata($u):null;$who=$user?$user->display_name:'TUFF BEATZ';$when=!empty($f['uploaded_at'])?mysql2date('M j, Y • g:i a',$f['uploaded_at']):'';$version=$f['version']?:'Project File';$fid=$f['id']??'';echo '<article class="tb-fm-asset"><div class="tb-fm-file"><span class="tb-fm-icon">'.esc_html(tuff_beatz_file_manager_icon($f['name']??'')).'</span><div class="tb-fm-file-main"><strong>'.esc_html($f['name']??'File').'</strong><span>'.esc_html($version).' • '.esc_html(tuff_beatz_vault_human_size($f['size']??0)).'</span></div><div class="tb-fm-meta"><small>UPLOADED BY</small><b>'.esc_html($who).'</b><span>'.esc_html($when).'</span></div><div class="tb-fm-actions"><a href="'.esc_url(tuff_beatz_vault_download_url($id,$fid)).'">Download ↓</a>';if($can_manage)echo '<button type="button" data-fm-edit>Manage</button>';echo '</div></div>';if($can_manage){echo '<div class="tb-fm-editor" hidden><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="tb_file_manager_update"><input type="hidden" name="request_id" value="'.esc_attr($id).'"><input type="hidden" name="file_id" value="'.esc_attr($fid).'">';wp_nonce_field('tb_fm_manage_'.$id.'_'.$fid,'tb_fm_manage_nonce');echo '<label class="tb-fm-field"><span>Display Name</span><input type="text" name="display_name" value="'.esc_attr($f['name']??'').'"></label><label class="tb-fm-field"><span>Version</span><input type="text" name="version" value="'.esc_attr($version).'"></label><label class="tb-fm-field"><span>Category</span><select name="studio_category">';$bucket=tuff_beatz_file_manager_bucket($f);foreach(tuff_beatz_file_manager_categories() as $ck=>$cl)echo '<option value="'.esc_attr($ck).'"'.selected($bucket,$ck,false).'>'.esc_html($cl).'</option>';echo '</select></label><button class="btn btn-gold" type="submit">Save Changes</button></form><div class="tb-fm-danger"><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="tb_file_manager_archive"><input type="hidden" name="request_id" value="'.esc_attr($id).'"><input type="hidden" name="file_id" value="'.esc_attr($fid).'">';wp_nonce_field('tb_fm_manage_'.$id.'_'.$fid,'tb_fm_manage_nonce');echo '<button type="submit">'.(!empty($f['archived'])?'Restore from Archive':'Archive File').'</button></form><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" onsubmit="return confirm(\'Permanently delete this private vault file? This cannot be undone.\');"><input type="hidden" name="action" value="tb_file_manager_delete"><input type="hidden" name="request_id" value="'.esc_attr($id).'"><input type="hidden" name="file_id" value="'.esc_attr($fid).'">';wp_nonce_field('tb_fm_delete_'.$id.'_'.$fid,'tb_fm_delete_nonce');echo '<button class="is-delete" type="submit">Delete Permanently</button></form></div></div>';}echo '</article>';}}
add_action('wp_footer','tuff_beatz_file_manager_render',5);
function tuff_beatz_file_manager_assets(){if(is_page('project-dashboard')){$p=get_template_directory().'/assets/css/file-manager.css';if(file_exists($p))wp_enqueue_style('tuff-beatz-file-manager',get_template_directory_uri().'/assets/css/file-manager.css',array('tuff-beatz-project-portal'),filemtime($p));}}
add_action('wp_enqueue_scripts','tuff_beatz_file_manager_assets',49);
